+    private static final String COMMON = """
+            "roomNumber": 201, "guestName": "%s", "guestEmail": "g@example.com",
+            "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"
