   132	    private static Identification readIdentification(CreateReservationRequest body) {
   133	        boolean cpf = !isBlank(body.guestCpf());
   134	        boolean company = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
   135	        boolean foreign = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());
   136	        if ((cpf ? 1 : 0) + (company ? 1 : 0) + (foreign ? 1 : 0) != 1) {
   137	            throw new HotelException(
   138	                    ErrorCode.INVALID_REQUEST,
   139	                    "identify the guest in exactly one way: guestCpf, or companyCnpj with companyName,"
   140	                            + " or guestPassport with guestCountry");
   141	        }
   142	        if (cpf) {
   143	            return new Identification.Cpf(body.guestCpf());
   144	        }
   145	        if (company) {
   146	            if (isBlank(body.companyCnpj()) || isBlank(body.companyName())) {
   147	                throw new HotelException(ErrorCode.INVALID_REQUEST, "a company needs companyCnpj and companyName");
   148	            }
   149	            return new Identification.Company(body.companyCnpj(), body.companyName());
   150	        }
   151	        if (isBlank(body.guestPassport()) || isBlank(body.guestCountry())) {
   152	            throw new HotelException(
   153	                    ErrorCode.INVALID_REQUEST, "a foreign guest needs guestPassport and guestCountry");
   154	        }
   155	        return new Identification.Foreign(body.guestPassport(), body.guestCountry());
   156	    }
